using System.ComponentModel.DataAnnotations; using System.Security.Claims; using Marina.Domain.Catalog; using Marina.Domain.Commerce; using Marina.Domain.Security; using Marina.Persistence.Data; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace Marina.Api.Controllers;
[ApiController,Authorize(Policy="StaffMfa"),Route("api/v1/admin"),Microsoft.AspNetCore.RateLimiting.EnableRateLimiting("admin")]
public sealed class AdminController(MarinaDbContext db):ControllerBase{
 public sealed record InventoryAdjustment(int Delta,[Required,MaxLength(300)]string Reason,StockMovementType Type);public sealed record StatusRequest(OrderStatus Status,[MaxLength(300)]string?Reason);public sealed record CouponRequest([Required,MaxLength(40)]string Code,DiscountType Type,decimal Value,decimal?MinimumPurchase,decimal?MaximumDiscount,DateTime ValidFromUtc,DateTime ValidToUtc,int?MaxUses,int?MaxUsesPerCustomer,bool IsActive);
 [HttpGet("dashboard"),Authorize(Policy="Reports.View")]public async Task<ActionResult>Dashboard(){var since=DateTime.UtcNow.Date.AddDays(-30);var sales=await db.Orders.Where(x=>x.CreatedUtc>=since&&x.Status!=OrderStatus.Cancelled).SumAsync(x=>(decimal?)x.Total)??0;var orders=await db.Orders.CountAsync(x=>x.CreatedUtc>=since);var customers=await db.Users.CountAsync(x=>x.CreatedUtc>=since);var lowStock=await db.Inventories.CountAsync(x=>x.Quantity-x.ReservedQuantity<=x.LowStockThreshold);var recent=await db.Orders.AsNoTracking().OrderByDescending(x=>x.CreatedUtc).Take(8).Select(x=>new{x.Id,x.PublicNumber,x.Status,x.Total,x.CreatedUtc}).ToListAsync();return Ok(new{sales,orders,newCustomers=customers,averageOrderValue=orders==0?0:sales/orders,lowStock,recentOrders=recent});}
 [HttpGet("inventory"),Authorize(Policy="Inventory.View")]public async Task<ActionResult>Inventory([FromQuery]bool lowStockOnly=false,[FromQuery]string?search=null,[FromQuery]int page=1,[FromQuery]int pageSize=30){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.Inventories.AsNoTracking();if(lowStockOnly)q=q.Where(x=>x.Quantity-x.ReservedQuantity<=x.LowStockThreshold);if(!string.IsNullOrWhiteSpace(search)){var term=search.Trim();q=q.Where(i=>db.ProductVariants.Any(v=>v.Id==i.ProductVariantId&&v.Sku.Contains(term)));}var total=await q.CountAsync();var items=await q.Join(db.ProductVariants,x=>x.ProductVariantId,x=>x.Id,(i,v)=>new{i.Id,i.ProductVariantId,v.Sku,i.Quantity,i.ReservedQuantity,Available=i.Quantity-i.ReservedQuantity,i.LowStockThreshold}).OrderBy(x=>x.Sku).Skip((page-1)*pageSize).Take(pageSize).ToListAsync();return Ok(new{items,page,pageSize,total});}
 [HttpPost("inventory/{variantId:guid}/adjust"),Authorize(Policy="Inventory.Adjust")]public async Task<IActionResult>Adjust(Guid variantId,InventoryAdjustment r){if(r.Delta==0||Math.Abs(r.Delta)>100000)return BadRequest();var inventory=await db.Inventories.SingleOrDefaultAsync(x=>x.ProductVariantId==variantId)??throw new KeyNotFoundException("Inventory not found.");var old=inventory.Quantity;var next=old+r.Delta;if(next<inventory.ReservedQuantity)return Conflict(new{message="Adjustment would reduce stock below reserved quantity."});inventory.Quantity=next;db.StockMovements.Add(new StockMovement{VariantId=variantId,Type=r.Type,OldQuantity=old,Delta=r.Delta,NewQuantity=next,Reason=r.Reason.Trim(),ActorId=UserId()});Audit("Inventory.Adjust",nameof(Inventory),inventory.Id,null,new{old,next,r.Reason});await db.SaveChangesAsync();return NoContent();}
 [HttpGet("orders"),Authorize(Policy="Orders.View")]public async Task<ActionResult>Orders([FromQuery]OrderStatus?status=null,[FromQuery]string?search=null,[FromQuery]int page=1,[FromQuery]int pageSize=30){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.Orders.AsNoTracking();if(status.HasValue)q=q.Where(x=>x.Status==status);if(!string.IsNullOrWhiteSpace(search)){var term=search.Trim();q=q.Where(x=>x.PublicNumber.Contains(term));}var total=await q.CountAsync();return Ok(new{items=await q.OrderByDescending(x=>x.CreatedUtc).Skip((page-1)*pageSize).Take(pageSize).Select(x=>new{x.Id,x.PublicNumber,x.UserId,x.Status,x.Total,x.CreatedUtc}).ToListAsync(),page,pageSize,total});}
 [HttpPut("orders/{id:guid}/status"),Authorize(Policy="Orders.UpdateStatus")]public async Task<IActionResult>Status(Guid id,StatusRequest r){var order=await db.Orders.SingleOrDefaultAsync(x=>x.Id==id)??throw new KeyNotFoundException("Order not found.");var old=order.Status;if(!AllowedOrderTransition(old,r.Status))return Conflict(new{message=$"Cannot change an order from {old} to {r.Status}. Use the dedicated cancellation or return workflow where applicable."});order.Status=r.Status;order.StatusHistory.Add(new OrderStatusHistory{Status=r.Status,ActorId=UserId(),Reason=r.Reason});Audit("Orders.UpdateStatus",nameof(Order),order.Id,new{old},new{r.Status,r.Reason});await db.SaveChangesAsync();return NoContent();}
 [HttpGet("coupons"),Authorize(Policy="Coupons.Manage")]public async Task<ActionResult>Coupons([FromQuery]string?search=null,[FromQuery]int page=1,[FromQuery]int pageSize=30){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var query=db.Coupons.AsNoTracking();if(!string.IsNullOrWhiteSpace(search)){var term=search.Trim();query=query.Where(x=>x.Code.Contains(term));}var ordered=query.OrderByDescending(x=>x.CreatedUtc);var total=await query.CountAsync();return Ok(new{items=await ordered.Skip((page-1)*pageSize).Take(pageSize).ToListAsync(),page,pageSize,total});}
 [HttpPost("coupons"),Authorize(Policy="Coupons.Manage")]public async Task<ActionResult>CreateCoupon(CouponRequest r){ValidateCoupon(r);var coupon=new Coupon{Code=r.Code.Trim().ToUpperInvariant(),Type=r.Type,Value=r.Value,MinimumPurchase=r.MinimumPurchase,MaximumDiscount=r.MaximumDiscount,ValidFromUtc=r.ValidFromUtc.ToUniversalTime(),ValidToUtc=r.ValidToUtc.ToUniversalTime(),MaxUses=r.MaxUses,MaxUsesPerCustomer=r.MaxUsesPerCustomer,IsActive=r.IsActive};db.Coupons.Add(coupon);Audit("Coupons.Create",nameof(Coupon),coupon.Id,null,r);await db.SaveChangesAsync();return Created("",coupon);}
 [HttpGet("audit"),Authorize(Policy="AuditLogs.View")]public async Task<ActionResult>AuditLogs([FromQuery]string?search=null,[FromQuery]int page=1,[FromQuery]int pageSize=50){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.AuditLogs.AsNoTracking();if(!string.IsNullOrWhiteSpace(search)){var term=search.Trim();q=q.Where(x=>x.Action.Contains(term)||x.EntityName.Contains(term));}return Ok(await q.OrderByDescending(x=>x.CreatedUtc).Skip((page-1)*pageSize).Take(pageSize).ToListAsync());}
 [HttpGet("security-events"),Authorize(Policy="AuditLogs.View")]public async Task<ActionResult>SecurityEvents([FromQuery]string?search=null,[FromQuery]int page=1,[FromQuery]int pageSize=50){page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var q=db.SecurityEvents.AsNoTracking();if(!string.IsNullOrWhiteSpace(search)){var term=search.Trim();q=q.Where(x=>x.EventType.Contains(term)||x.IpAddress.Contains(term)||x.Severity.Contains(term));}return Ok(await q.OrderByDescending(x=>x.CreatedUtc).Skip((page-1)*pageSize).Take(pageSize).ToListAsync());}
 private void Audit(string action,string entity,Guid id,object?oldValues,object?newValues)=>db.AuditLogs.Add(new AuditLog{UserId=UserId(),Action=action,EntityName=entity,EntityId=id.ToString(),IpAddress=HttpContext.Connection.RemoteIpAddress?.ToString()??"unknown",CorrelationId=HttpContext.TraceIdentifier,OldValuesJson=oldValues is null?null:System.Text.Json.JsonSerializer.Serialize(oldValues),NewValuesJson=newValues is null?null:System.Text.Json.JsonSerializer.Serialize(newValues)});private static bool AllowedOrderTransition(OrderStatus current,OrderStatus next)=>(current,next) switch{(OrderStatus.Pending,OrderStatus.Confirmed)=>true,(OrderStatus.Confirmed,OrderStatus.Preparing)=>true,(OrderStatus.Preparing,OrderStatus.Ready)=>true,(OrderStatus.Ready,OrderStatus.Shipped)=>true,(OrderStatus.Shipped,OrderStatus.OutForDelivery)=>true,(OrderStatus.OutForDelivery,OrderStatus.Delivered)=>true,_=>false};private static void ValidateCoupon(CouponRequest r){if(r.Value<=0||r.ValidToUtc<=r.ValidFromUtc||r.Type==DiscountType.Percentage&&r.Value>100)throw new ArgumentException("Invalid coupon rules.");}private Guid UserId()=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
}
